import{_ as t,a as n}from"./chunks/download-card-ok.DWtS-PB7.js";import{c as s,Q as o,j as r,m as a}from"./chunks/framework.BqPkuuVc.js";const i="/assets/docs-start-onboarding-welcome.b5yg639c.png",h="/assets/event-list-no-events.D93cJVvs.png",l="/assets/machine-name-prompt.DsjhzP8X.png",g="/assets/docs-start-event-list-samples.YOX5_DH9.png",d="/assets/docs-start-event-list-history.BpT-GHZb.png",c="/assets/event-list-eventor-upcoming.rvm9RXMh.png",p="/assets/docs-start-restore-dialog.CTDh36jH.png",u="/assets/docs-start-sample-events.VUUAkK5a.png",m="/assets/event-list-new-event-menu.C5nMA5jT.png",v="/assets/new-event-dialog-manual-with-eventor.pHF-Qytn.png",f="/assets/edit-event-details.DUraJLwx.png",w="/assets/docs-start-add-course-controls.D1iCeyS2.png",b="/assets/docs-start-add-class.DzYu-dCN.png",y="/assets/competitors-add-dialog.CDPB_Qru.png",k="/assets/docs-start-dashboard-setup.1ZX77fu5.png",S="/assets/event-nav-search.CGpgPtMz.png",T="/assets/event-nav-collapsed.BO0LLf6N.png",C="/assets/alerts-panel-expanded.DAKDmoNY.png",_="/assets/docs-start-language-menu.B_DLaU0I.png",E="/assets/docs-start-validation-warnings.ARj9OnMY.png",q="/assets/download-card.C2Lhhf2x.png",x="/assets/radio-punches.ZjHm5tdY.png",I="/assets/leaderboard-pinned-places.HavwdWob.png",P="/assets/docs-start-screens.DVBBCWaz.png",A="/assets/results-publish-menu.yfddCcuP.png",O="/assets/event-state-menu.DxhCm_qt.png",M="/assets/event-not-finalised-finish.BP8IGkOP.png",H=JSON.parse('{"title":"Walkthrough: your first event","description":"","frontmatter":{},"headers":[],"relativePath":"user/getting-started/first-event-walkthrough.md","filePath":"user/getting-started/first-event-walkthrough.md"}'),R={name:"user/getting-started/first-event-walkthrough.md"};function D(L,e,F,N,B,W){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="walkthrough-your-first-event" tabindex="-1">Walkthrough: your first event <a class="header-anchor" href="#walkthrough-your-first-event" aria-label="Permalink to &quot;Walkthrough: your first event&quot;">​</a></h1><p><strong>Audience:</strong> New users — an organiser or timing operator trying Manager for the first time.</p><p>An end-to-end tour: create a small event, add some data, download a card, and view results. Everything a real event needs, but small enough to do in an afternoon at home. Each step links to a deeper page if you want the full details, and the screenshots show what you should see at each step.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>You&#39;ll need:</p><ul><li><strong>Manager installed and running</strong> on one computer (the &quot;server&quot;). See <a href="./../download-and-install/">Installing meshO Manager</a> if you haven&#39;t done this yet.</li><li><strong>A web browser</strong> on the same computer, or on any other device on the same network. <strong>Chrome, Edge or Firefox 151+ is required</strong> if you want to download cards or read a SportIdent station&#39;s memory — both rely on Web Serial, which Safari and older Firefox don&#39;t support. For everything else, any modern browser works.</li><li><strong>Optionally</strong>, a SportIdent USB reader station (BSM7-USB or BSM8-USB) and one or two <a href="./concepts-glossary#how-timing-data-arrives">cards</a>, if you want to test card download. You can skip the download steps if you don&#39;t have the hardware — everything else works without it. Plug the reader into the <strong>server computer</strong> for this walkthrough: a reader on another laptop also needs HTTPS set up first (see <a href="./../reference/https-and-certificates">HTTPS and certificates</a>). On a Mac, install SportIdent&#39;s USB driver first — see <a href="./../reference/sportident-usb-on-macos">SportIdent USB stations on macOS</a>.</li></ul><blockquote><p><strong>Tip:</strong> You don&#39;t need meshO Prime, radio controls, or a course in the forest to complete this walkthrough. Those are covered in <a href="./../running-the-event/connecting-prime-and-radios">Connecting meshO Prime and radios</a>.</p></blockquote><h2 id="the-modes-of-an-event" tabindex="-1">The modes of an event <a class="header-anchor" href="#the-modes-of-an-event" aria-label="Permalink to &quot;The modes of an event&quot;">​</a></h2><p>Every event in Manager moves through three modes:</p><ol><li><strong>Setup</strong> — the event is being built. You configure classes, courses, controls, competitors, and start times. The state button reads <strong>Setup</strong>.</li><li><strong>Live</strong> — the event is running. Card downloads work, radio punches flow in, and results are calculated in real time. The <strong>event date</strong> becomes locked; everything else — competitors, classes, start times, course assignments — remains editable, so late entries and on-the-day corrections still work. The state button reads <strong>Live</strong>.</li><li><strong>Archive</strong> — the event is finished. You can still view and export everything, and <strong>Restart event</strong> takes it live again if a late card turns up. The state button reads <strong>Complete</strong>.</li></ol><p>You move between them with the <strong>state button</strong> at the right of the app bar at the top of the screen. It shows the event&#39;s current state, coloured to match, and clicking it opens a menu with the next step: <strong>Start event</strong> to begin, <strong>Finish event</strong> to complete, and <strong>Events</strong> to go back to the event list.</p><p>Two other states are exceptions rather than modes: <strong>Interrupted</strong> — the event was live when Manager stopped, and is waiting for you to choose <strong>Resume event</strong> — and <strong>Abandoned</strong>, an interrupted event you chose not to resume. Either can be resumed or marked finished later. See <a href="./../running-the-event/dashboard">The event dashboard</a>.</p><h2 id="_1-open-manager" tabindex="-1">1. Open Manager <a class="header-anchor" href="#_1-open-manager" aria-label="Permalink to &quot;1. Open Manager&quot;">​</a></h2><p>Open your browser and navigate to the Manager URL. If you&#39;re on the server PC itself, this is usually <code>http://localhost:5154/manager</code> (the default — the port can be changed in <strong>Settings → <a href="./../reference/settings#server">Server</a></strong>).</p><h3 id="the-welcome-tour" tabindex="-1">The welcome tour <a class="header-anchor" href="#the-welcome-tour" aria-label="Permalink to &quot;The welcome tour&quot;">​</a></h3><p>The first time Manager is opened, a short <strong>Welcome tour</strong> runs first. It is ten steps, each with <strong>Next</strong>, <strong>Back</strong> and <strong>Skip</strong>, and a row of dots you can click to jump to a step:</p><p><img src="'+i+'" alt="The first step of the welcome tour: the meshO Manager logo, a short welcome, and a grid of flags under Choose your language"></p><ul><li><strong>Welcome</strong> — choose your language. It becomes the installation&#39;s default language.</li><li><strong>Light or dark, your choice</strong> — the theme, saved for this computer only.</li><li><strong>From small events to major carnivals</strong> and <strong>Install once, connect from anywhere</strong> — how Manager is used, from one laptop to a whole arena.</li><li><strong>meshO Radios</strong> — switch on <strong>Use meshO Prime for radio punches</strong> if you have meshO radios.</li><li><strong>Eventor</strong> — switch on <strong>Use Eventor</strong> and enter the <strong>Host name</strong> and <strong>API key</strong> if your federation uses it.</li><li><strong>Spectator, Kiosk &amp; Leaderboard screens</strong> — the displays for the public.</li><li><strong>Ask for help</strong> — how much the <a href="./../reference/built-in-assistant">built-in assistant</a> may answer.</li><li><strong>Protect Manager with a PIN</strong> — <strong>Require a PIN to open Manager</strong>, if this computer is on a network the public can reach.</li><li><strong>You&#39;re ready to go! Enjoy!</strong> — finish with <strong>Get started</strong>.</li></ul><p><strong>Skip</strong> (or the cross in the corner) closes it; a skipped tour comes back the next time Manager is opened, until you finish it. You can replay it any time with the <strong>Welcome tour</strong> button in the top bar of the Events page.</p><h3 id="the-events-page" tabindex="-1">The Events page <a class="header-anchor" href="#the-events-page" aria-label="Permalink to &quot;The Events page&quot;">​</a></h3><p>You&#39;ll land on the <strong>Events</strong> page. On a fresh install it says <strong>Welcome to meshO Manager</strong>, with a <strong>New event</strong> button, <strong>Restore from backup</strong>, <strong>Try a sample event</strong> (when the installation ships example events) and <strong>Live standby</strong>:</p><p><img src="'+h+'" alt="The Events page on a fresh install: the orange welcome banner with New event, Restore from backup, Try a sample event and Live standby, and a note to visit Settings first"></p><p>Underneath, <strong>Before you create your first event</strong> suggests a visit to <strong>Settings</strong> first — the gear icon at the top right — for anything you want applied to every new event. See <a href="./../reference/settings">Settings</a>.</p><blockquote><p><strong>Note:</strong> On any computer <em>other</em> than the server, Manager also asks you to <strong>Name this computer</strong> the first time — a name like &quot;Download lane A&quot; makes the <a href="./../reference/audit-trail#naming-a-computer">audit trail</a> easier to read. Type one and <strong>Save</strong>, or choose <strong>Not now</strong>. The server&#39;s own browser (opened at <code>localhost</code>) isn&#39;t asked.</p><p><img src="'+l+'" alt="The Name this computer dialog, with a Computer name field and a list of computers set up before"></p></blockquote><p>Once you have events, the page looks like this:</p><p><img src="'+g+'" alt="The Events page with a live event in the green banner at the top, the Upcoming and History tabs, and two event cards"></p><table tabindex="0"><thead><tr><th>Part of the page</th><th>What it does</th></tr></thead><tbody><tr><td><strong>The banner</strong></td><td>Green with <strong>LIVE</strong> while an event is running, blue with <strong>TODAY</strong> for today&#39;s event not yet started, orange (<strong>Create new event</strong>) otherwise. <strong>Open event</strong> goes straight to it.</td></tr><tr><td><strong>Upcoming</strong> / <strong>History</strong> tabs</td><td>Upcoming lists events still to run (soonest first); <strong>History</strong> lists finished ones (most recent first), with <strong>Search events…</strong>.</td></tr><tr><td><strong>New</strong></td><td>Creates an event — see <a href="#_2-create-an-event">step 2</a>. With Eventor switched on it opens a menu: <strong>Create manually…</strong> or <strong>Import from Eventor…</strong>.</td></tr><tr><td><strong>Restore</strong></td><td><strong>Restore from backup</strong> — from a <strong>Local file</strong> or one saved on the server (<strong>From server</strong>). See <a href="./../reference/backup-and-restore#restoring-an-event">Backup and restore</a>.</td></tr><tr><td><strong>Samples</strong></td><td>The bundled example events — see <a href="#a-shortcut-add-a-sample-event">below</a>. Only shown when the installation ships some.</td></tr><tr><td><strong>Live standby</strong></td><td>Makes this computer a live copy of an event on another one. See <a href="./../running-the-event/live-standby">Live standby</a>.</td></tr><tr><td><strong>Multi-event</strong></td><td>Jobs across several events at once: <strong>Allocate bib numbers…</strong>, <strong>Import bib numbers…</strong> (<a href="./../event-setup/bib-numbers">Bib numbers</a>) and <strong>Seed from IOF ranking…</strong> (<a href="./../event-setup/iof-ranking">IOF ranking</a>).</td></tr><tr><td><strong>Each event card</strong></td><td>Name, date, the event&#39;s facts (type, level, discipline, start), its state, and — on hover — <strong>Push to cloud</strong>, <strong>Backup event</strong>, <strong>Duplicate event</strong> and <strong>Delete event</strong>. Click the card to open the event.</td></tr><tr><td><strong>Upcoming on Eventor</strong></td><td>With Eventor set up, your organisation&#39;s upcoming Eventor events, each with <strong>Create event</strong>. <strong>Choose events</strong> opens <strong>Settings → Eventor</strong>. See <a href="./../event-setup/create-event-from-eventor">Creating an event from Eventor</a>.</td></tr></tbody></table><p><img src="'+d+'" alt="The History tab: finished events with a Complete chip and a cloud icon, and the Search events box"></p><p><img src="'+c+'" alt="Upcoming on Eventor, below your own events: three Eventor events, each with a Create event button, and Choose events at the top"></p><p><img src="'+p+'" alt="The Restore from backup dialog with its Local file and From server tabs, and Choose file…"></p><p>The buttons in the top bar of the Events page are, from left to right: <strong>meshO Radios</strong> (with meshO Prime switched on and no event live), <strong>Station configuration</strong> (<a href="./../reference/station-configuration">Station configuration</a>), <strong>Extensions</strong> (<a href="./../advanced/installing-extensions#the-extensions-page">Installing extensions</a>), <strong>Welcome tour</strong>, <strong>Documentation</strong> (these pages) and <strong>Settings</strong>. The flag at the far right is the language and theme menu — see <a href="#language-and-theme">Language and theme</a>.</p><p>If Manager stopped while an event was live, the Events page asks <strong>Resume event?</strong> as soon as it opens. <strong>Resume event</strong> takes it live again; <strong>Not now</strong> leaves it <strong>Interrupted</strong>. See <a href="./../running-the-event/dashboard">The event dashboard</a>.</p><h2 id="a-shortcut-add-a-sample-event" tabindex="-1">A shortcut: add a sample event <a class="header-anchor" href="#a-shortcut-add-a-sample-event" aria-label="Permalink to &quot;A shortcut: add a sample event&quot;">​</a></h2><p>If you&#39;d rather look at a finished event than build one, click <strong>Try a sample event</strong> (or <strong>Samples</strong>, once you have events of your own) and then <strong>Add</strong> beside the one you want. A sample you&#39;ve already added says <strong>Already in your events</strong>; <strong>Add</strong> opens your copy.</p><p><img src="'+u+'" alt="The Sample events dialog listing three example events, each with an Add button; one says Already in your events"></p><p>Manager ships with complete example events — real classes, courses, competitors, card downloads and results. Adding one puts a copy in your event list, dated today, exactly as though you had run it yourself: browse the results and splits, print splits, put a screen up, or use <strong>Replay</strong> to watch the event unfold as if it were happening now (see <a href="./../running-the-event/dashboard">The event dashboard</a>). Change it or delete it whenever you like — it&#39;s an ordinary event and affects nothing else.</p><p>Adding a sample is the fastest way to see what a finished event looks like. Come back here afterwards to build one of your own. Everything else on the Events page — the event cards, their actions, the History tab — is described in <a href="./../event-setup/create-event#the-events-page">Creating an event</a>.</p><h2 id="_2-create-an-event" tabindex="-1">2. Create an event <a class="header-anchor" href="#_2-create-an-event" aria-label="Permalink to &quot;2. Create an event&quot;">​</a></h2><p>Click <strong>New event</strong> (and, if you have Eventor switched on, <strong>Create manually…</strong> from the menu it opens).</p><p><img src="'+m+'" alt="The New menu open under the New button, offering Create manually… and Import from Eventor…"></p><p>The <strong>New event</strong> dialog asks for the <strong>Event name</strong> and <strong>Event date</strong>, both already filled in — the name after the day of the week the date falls on (e.g. &quot;Thursday event&quot;), the date with today — and what you&#39;re creating, as three cards: <strong>Individual</strong>, <strong>Relay</strong> or <strong>Multi-stage event</strong>.</p><p><img src="'+v+'" alt="The New event dialog: Event name, Event date, and the Individual, Relay and Multi-stage event cards with Individual selected"></p><p>Type something more recognisable like &quot;Test Event&quot; over the name, leave the date as today and the <strong>Individual</strong> card selected, then click <strong>Create</strong>. Manager creates the event in <strong>Setup</strong> with the defaults from <strong>Settings → <a href="./../reference/settings#event-defaults">Event defaults</a></strong> and takes you straight to its <strong>Dashboard</strong>. (A <a href="./../event-setup/relay-events">relay</a> also asks for the number of legs; a <a href="./../event-setup/multi-stage-events">multi-stage event</a> groups several events into one.)</p><p>If you want to change the name or date later, you can:</p><ol><li>On the dashboard, click <strong><a href="./../event-setup/create-event#editing-event-details">Event details</a></strong> at the top left.</li><li>Change <strong>Event name</strong> (and <strong>Event date</strong>, if you want a future date) on the <strong>Details</strong> tab.</li><li>Click <strong>Save</strong>.</li></ol><p><img src="'+f+'" alt="The Event details dialog on its Details tab, with the list of other tabs down the left"></p><blockquote><p><strong>Shortcut — import from Eventor:</strong> If your organisation uses Eventor and you&#39;ve already configured the connection in <strong>Settings → Eventor</strong>, you can choose <strong>Import from Eventor…</strong> from that same button instead. Manager will fetch a list of events, let you pick one, and import classes, competitors, clubs, and start times in one step. If you go this route, you can skip ahead to <a href="#_6-explore-the-dashboard">step 6 (the dashboard)</a>. See <a href="./../event-setup/create-event-from-eventor">Creating an event from Eventor</a> for the full details.</p></blockquote><h2 id="_3-create-a-course" tabindex="-1">3. Create a course <a class="header-anchor" href="#_3-create-a-course" aria-label="Permalink to &quot;3. Create a course&quot;">​</a></h2><p>Before you start the event, you need at least one <a href="./concepts-glossary#the-course-and-the-controls">course</a>. For this test, you&#39;ll make a short one.</p><ol><li>In the event menu on the left, click <strong>Course</strong> (at the top, beside <strong>Entries</strong> and <strong>Race</strong>), then <strong>Courses</strong>.</li><li>Click <strong>Actions → Add…</strong>. The <strong>Add course</strong> dialog opens.</li><li>On the <strong>Details</strong> tab, give the course a <strong>Course name</strong> — for example &quot;Short&quot;. Leave <strong>Course format</strong> as it is (a line course, visited in order, unless the event is set up for scatter courses).</li><li>Open the <strong>Controls</strong> tab. Type each control code and press <strong>Enter</strong> after each one. For example, type <code>31</code>, Enter, <code>32</code>, Enter, <code>33</code>, Enter. The controls appear as chips that you can drag to reorder.</li><li>Click <strong>Save</strong>.</li></ol><p><img src="'+w+'" alt="The Add course dialog on its Controls tab, with controls 31, 32 and 33 entered as chips"></p><p>You now have a 3-control course. The controls are created automatically as you add them.</p><blockquote><p><strong>Tip:</strong> In a real event, you&#39;d typically import courses from a Purple Pen file or IOF XML rather than typing them by hand. See <a href="./../event-setup/classes-and-courses">Classes and courses</a>.</p></blockquote><h2 id="_4-create-a-class-and-assign-the-course" tabindex="-1">4. Create a class and assign the course <a class="header-anchor" href="#_4-create-a-class-and-assign-the-course" aria-label="Permalink to &quot;4. Create a class and assign the course&quot;">​</a></h2><p>A <a href="./concepts-glossary#the-event-and-its-people"><em>class</em></a> is a category of competitors (e.g. M21E, W18A). A class typically runs a single course — although more than one can be assigned if you need it.</p><ol><li>In the event menu, click <strong>Entries</strong>, then <strong>Classes</strong>.</li><li>Click <strong>Actions → Add…</strong>.</li><li>Enter a <strong>Class name</strong> — for example &quot;Open&quot;.</li><li>In the <strong>Courses</strong> field, select the &quot;Short&quot; course you just created.</li><li>Click <strong>Save</strong>.</li></ol><p><img src="'+b+'" alt="The Add class dialog with Class name &quot;Open&quot;, an empty Courses field, and the Class mass start switch"></p><blockquote><p><strong>Tip:</strong> For a quick event where each course is its own class, turn on <strong>Create class</strong> in the <strong>Add course</strong> dialog, or use <strong>Auto create classes from courses…</strong> from either page&#39;s <strong>Actions</strong> menu. See <a href="./../event-setup/classes-and-courses">Classes and courses</a>.</p></blockquote><h2 id="_5-add-a-few-competitors" tabindex="-1">5. Add a few competitors <a class="header-anchor" href="#_5-add-a-few-competitors" aria-label="Permalink to &quot;5. Add a few competitors&quot;">​</a></h2><ol><li>In the event menu, under <strong>Entries</strong>, click <strong>Competitors</strong>.</li><li>Click <strong>Actions → Add…</strong>.</li><li>Fill in <strong>First name</strong> and <strong>Surname</strong>, and choose the &quot;Open&quot; class under <strong>Class</strong>.</li><li>If you have a card, enter its number in the <strong>Card number</strong> field. Otherwise leave it blank for now.</li><li>Click <strong>Save</strong>, and repeat for one or two more competitors. (Turn on <strong>Keep adding</strong> to keep the dialog open for the next one.)</li></ol><p><img src="'+y+'" alt="The Add competitor dialog: First name, Surname, Class, Club, Card number and the other fields"></p><p>You should now see your competitors listed with their class, and a status of <strong>None</strong> (no result yet).</p><blockquote><p><strong>Tip:</strong> In a real event, competitors and their card numbers come from the entry system (Eventor, IOF XML import, or on-the-day registration). Typing them by hand is only needed for small events or late entries. See <a href="./../event-setup/competitors-clubs-teams">Competitors, clubs and teams</a>.</p></blockquote><h2 id="_6-explore-the-dashboard" tabindex="-1">6. Explore the dashboard <a class="header-anchor" href="#_6-explore-the-dashboard" aria-label="Permalink to &quot;6. Explore the dashboard&quot;">​</a></h2><p>Click <strong>Dashboard</strong> at the top of the event menu.</p><p><img src="'+k+'" alt="The dashboard of an event in Setup: the Setup button at the top right, the Entries menu on the left, and the Event data, Competitors, Quick actions, Download card and Spectators tiles"></p><p>The dashboard is your central view during an event. Along its top are <strong><a href="./../event-setup/create-event#editing-event-details">Event details</a></strong> (the event&#39;s settings, from name and date to printing and backups) and <strong>Edit dashboard</strong>, which lets you move, resize and hide the tiles below. Then you&#39;ll see several tiles:</p><ul><li><strong>Event data</strong> — how many controls, courses, classes, competitors, teams and clubs the event holds, with an <strong>Import</strong> button.</li><li><strong>Competitors</strong> — counts by status: <strong>Total</strong>, <strong>Not started</strong>, <strong>Started</strong>, <strong>On course</strong>, <strong>Pending</strong> and <strong>Finished</strong>, with a chart of how many are on course over time. In a brand-new event everyone is <strong>Not started</strong>.</li><li><strong>Quick actions</strong> — a quick-search panel where you can look up any competitor, change their card number, reassign them to a different class on the fly, or print their splits. You can also add a new competitor from here.</li><li><strong>Download card</strong> — the card reader&#39;s status and the latest download. Until the event is live it says <strong>Card download is available while the event is running.</strong></li><li><strong>Spectators</strong> — once the event is live, how many people are following the event on the <a href="./../screens/spectator-site-and-kiosk">spectator site and kiosk</a>.</li></ul><p>Other tiles appear depending on your event configuration:</p><ul><li><strong>Radio controls</strong> — when the event uses meshO Prime radios.</li><li><strong>Radio punch forwarding</strong> / <strong>SIRAP punch listening</strong> — when the event forwards or accepts punches over the network.</li><li><strong>Liveresultat</strong> — when the event publishes to liveresultat.orientering.se.</li><li><strong>Recent downloads</strong> and <strong>Pending downloads</strong> — off to begin with; add them with <strong>Edit dashboard</strong>.</li><li><strong>Extension tiles</strong> — any tiles contributed by installed extensions.</li></ul><p>Don&#39;t worry about the conditional tiles for this test. For the full tour of every dashboard card, see <a href="./../running-the-event/dashboard">The event dashboard</a>.</p><h3 id="finding-your-way-around-an-event" tabindex="-1">Finding your way around an event <a class="header-anchor" href="#finding-your-way-around-an-event" aria-label="Permalink to &quot;Finding your way around an event&quot;">​</a></h3><p>Every event page has the same frame around it.</p><p><strong>The app bar</strong> across the top shows the event&#39;s name, its date and facts (type, level, discipline, start type), and on the right:</p><ul><li><strong>Ask</strong> (the robot face) — the <a href="./../reference/built-in-assistant">built-in assistant</a>, when it is switched on.</li><li><strong>The event clock</strong> — the running event time while the event is live.</li><li><strong>The state button</strong> — <strong>Setup</strong>, <strong>Live</strong>, <strong>Complete</strong> and so on, with the menu that starts and finishes the event.</li></ul><p><strong>The event menu</strong> down the left starts with <strong>Dashboard</strong>, then a switch between three modes, each with its own screens:</p><table tabindex="0"><thead><tr><th>Mode</th><th>Screens</th></tr></thead><tbody><tr><td><strong>Course</strong></td><td><strong>Courses</strong>, <strong>Controls</strong>, <strong>Legs</strong>, <strong>Map</strong></td></tr><tr><td><strong>Entries</strong></td><td><strong>Competitors</strong>, <strong>Classes</strong>, <strong>Clubs</strong>, <strong>Relay teams</strong> (relay events), <strong>Starts</strong>, <strong>Hire items</strong></td></tr><tr><td><strong>Race</strong></td><td><strong>Card downloads</strong>, <strong>Radio punches</strong>, <strong>Radios</strong>, <strong>Live view</strong>, <strong>Tracking</strong>, <strong>Results</strong>, <strong>Leaderboard</strong>, and under <strong>Admin</strong>: <strong>SportIdent station</strong>, <strong>Screens</strong>, <strong>Spectators</strong>, <strong>Audit trail</strong></td></tr></tbody></table><p>An event in Setup opens on <strong>Entries</strong>; a live or finished one on <strong>Race</strong>. The numbers beside a screen are how many items it holds. Screens about radios and Prime appear only when the event uses them, and screens such as <strong>Card downloads</strong> open before the start too, saying what fills them in once the event is live.</p><p>At the foot of the menu, <strong>Go to…</strong> (or <strong>Ctrl+K</strong>, <strong>⌘K</strong> on a Mac) finds any screen, <strong><a href="./../event-setup/create-event#editing-event-details">Event settings</a></strong> itself and any of its tabs, by typing part of its name. It also opens what the dashboard does, from any page: <strong>Add competitor</strong>, <strong>Import</strong> (courses, classes, entries and start times), the <strong>On course</strong>, <strong>Not started</strong> and <strong>Pending</strong> (competitors not downloaded) lists, <strong>Events</strong>, which closes the event and goes back to the events list (type <strong>close</strong> to find it), and <strong>Ask the assistant</strong> where the assistant is switched on. Whichever of <strong>Start event</strong>, <strong>Resume event</strong>, <strong>Finish event</strong> and <strong>Mark finished</strong> the event&#39;s state menu offers right now is listed too, and asks for the same confirmation. The list opens as soon as the search does: the up and down arrows move through it, and <strong>Enter</strong> opens the highlighted entry. Typing <strong>settings</strong> lists every tab of Event settings, and <strong>map</strong> finds the <strong>Live view</strong> as well as the <strong>Map</strong>. With the menu folded, <strong>Ctrl+K</strong> opens the search in the middle of the page and leaves the menu folded.</p><p><img src="'+S+'" alt="The Go to… search at the foot of the event menu, with &quot;se&quot; typed and Classes and Courses offered"></p><p>The <strong>≡</strong> button beside <strong>Dashboard</strong> folds the menu to a column of icons; each mode&#39;s screens then open beside it. A window narrower than 1024 pixels starts folded.</p><p><img src="'+T+'" alt="The event menu folded to icons, with the Race mode&#39;s screens open beside the column"></p><h3 id="the-alerts-panel" tabindex="-1">The alerts panel <a class="header-anchor" href="#the-alerts-panel" aria-label="Permalink to &quot;The alerts panel&quot;">​</a></h3><p>The narrow strip on the right of every event page is the <strong>Alerts</strong> panel, folded away. Click the arrow at its top to open it. <strong>Alerts</strong> lists the serious problems that need someone to act — a radio&#39;s battery critically low, a lost connection — and <strong>Messages</strong> below keeps a running log of everything reported, including alerts already dealt with. The panel opens by itself when a new alert arrives, and the strip shows meshO Prime&#39;s connection state at its foot.</p><p><img src="'+C+'" alt="The Alerts panel open on the right, with a critical battery alert under Alerts, and three entries under Messages"></p><p>The cross on an alert dismisses it: it leaves the <strong>Alerts</strong> list but stays under <strong>Messages</strong>, and a fresh alert appears if the problem changes again. See <a href="./../running-the-event/connecting-prime-and-radios">Connecting meshO Prime and radios</a> for the radio alerts you&#39;ll meet most.</p><h3 id="language-and-theme" tabindex="-1">Language and theme <a class="header-anchor" href="#language-and-theme" aria-label="Permalink to &quot;Language and theme&quot;">​</a></h3><p>The flag at the top right of the Events page (and of the <a href="./../running-the-event/registration-desk">registration desk</a>, <a href="./../screens/info-screens">info displays</a>, <a href="./../screens/spectator-site-and-kiosk">spectator site</a> and kiosk) opens a menu of languages, with three theme buttons underneath: follow the device, light and dark. Both choices are saved for this computer only, so every operator can have their own. See <a href="./../reference/settings#this-computer">Settings → This computer</a> for the rest of this computer&#39;s display settings.</p><p><img src="'+_+'" alt="The language and theme menu open under the flag: a grid of flags and three theme buttons"></p><h2 id="_7-start-the-event" tabindex="-1">7. Start the event <a class="header-anchor" href="#_7-start-the-event" aria-label="Permalink to &quot;7. Start the event&quot;">​</a></h2><p>Downloads, radio punches, and live results only happen once the event is in progress. Right now your event is still in <strong>Setup</strong>.</p><p>Click the <strong>Setup</strong> button at the right of the app bar. (On arriving at an event in Setup, this menu opens by itself for a few seconds.) It says <strong>Event is not live</strong> and offers <strong>Start event</strong>, with <strong>Events</strong> underneath to go back to the event list. (<strong>Replay</strong> also appears on an event with a recorded day to play back, such as a sample.)</p><p><img src="'+t+'" alt="The Setup state menu open: &quot;Event is not live&quot;, a Start event button, Replay, and Events — Back to events list"></p><p>Click <strong>Start event</strong>. Manager checks your event for problems first — no courses, no classes, no competitors, classes with no course assigned, competitors due to leave the start together — and if everything looks good, takes the event <strong>Live</strong>. The state button turns green and reads <strong>Live</strong>, the event clock starts, and the menu now offers <strong>Finish event</strong> (for later). <a href="./../running-the-event/dashboard#starting-and-finishing">Starting and finishing</a> on the dashboard page covers every state and what each one offers.</p><blockquote><p><strong>Tip:</strong> If Manager finds a problem, an <strong>Event validation warnings</strong> dialog lists what it found and asks whether to start anyway. Click <strong>Continue</strong> to start regardless, or <strong>Cancel</strong>, fix the issue, and click <strong>Start event</strong> again.</p><p><img src="'+E+'" alt="The Event validation warnings dialog: &quot;The following classes have no course assigned: Open&quot;, with Cancel and Continue"></p></blockquote><blockquote><p><strong>Note:</strong> An event dated in the future asks whether to <strong>Start in test mode</strong> instead, so keep this test event&#39;s date as today. An event whose date has passed without ever being run can&#39;t be started until you change its date. A second event can be live at the same time; see <a href="./../running-the-event/two-events-at-once">Running two events at once</a>.</p></blockquote><h2 id="_8-download-a-card" tabindex="-1">8. Download a card <a class="header-anchor" href="#_8-download-a-card" aria-label="Permalink to &quot;8. Download a card&quot;">​</a></h2><blockquote><p><strong>Skip this step</strong> if you don&#39;t have a SportIdent USB reader and a card.</p><p><strong>Browser requirement:</strong> this step needs Chrome, Edge or Firefox 151+ — the SI reader uses the Web Serial API, which Safari and older Firefox don&#39;t support.</p></blockquote><p>This is the core during-event action: a competitor finishes, hands in their card, and you read it.</p><ol><li>In the event menu, under <strong>Race</strong>, click <strong>Card downloads</strong>.</li><li>The <strong>SportIdent</strong> panel says <strong>Connect a SportIdent reader to download cards.</strong> with a <strong>Select device</strong> button.</li><li>Plug your SI reader into a USB port, then click <strong>Select device</strong>. Your browser will show a system dialog listing available serial devices — pick the SportIdent reader and confirm.</li><li>The status changes to <strong>Listening</strong>. The page now says <strong>Insert SportIdent card</strong>.</li></ol><p><img src="'+q+'" alt="The Card downloads page before a reader is connected: the SportIdent panel with Select device, and the Downloads table on the right"></p><p>Now insert the card in the reader:</p><ul><li>A progress bar appears while the card is read.</li><li>If the card number matches a competitor you entered in step 5, you&#39;ll see a green <strong>OK</strong> banner with the competitor&#39;s name, class, place and time.</li><li>If the card number doesn&#39;t match anyone, you&#39;ll see an orange <strong>Unassigned</strong> banner. Manager gives you the option to assign it to an existing competitor or create a new one right there.</li><li>If the card is missing a required punch, you&#39;ll see a <strong>Missing Punch (MP)</strong> result. You can change the competitor&#39;s class to one where the punches are valid, or later approve the missed control on their <strong>Overrides</strong> tab (see <a href="./../running-the-event/resolving-issues#competitor-results">Resolving issues on the day</a>).</li></ul><p><img src="'+n+'" alt="A green OK banner for Alex Johnson, M21E, place 3 of 34, with the Downloads table listing every card read"></p><p>The right side of the page is the <strong>Downloads</strong> table with every card you&#39;ve read — searchable, with a <strong>Filter</strong> button. Underneath the reader panel, the <a href="./../running-the-event/splits-printing">splits printer</a> and result-label printer this computer prints to are shown, with <strong>Change</strong>.</p><p>For the full details on every download scenario, see <a href="./../running-the-event/card-download">Downloading cards</a>.</p><h2 id="_9-see-radio-punches-optional" tabindex="-1">9. See radio punches (optional) <a class="header-anchor" href="#_9-see-radio-punches-optional" aria-label="Permalink to &quot;9. See radio punches (optional)&quot;">​</a></h2><p>If you have meshO Prime connected with radio controls in the field, the <strong>Radio punches</strong> page (under <strong>Race</strong>) shows punches arriving in real time — a table of card number, competitor name, control and punch time, with the most recent at the top.</p><p><img src="'+x+'" alt="The Radio punches page: three punches at the Spectator control, newest first"></p><p>For this at-home test you probably don&#39;t have a radio network, so feel free to skip this. See <a href="./../running-the-event/radio-punches">Radio punches</a> and <a href="./../running-the-event/connecting-prime-and-radios">Connecting meshO Prime and radios</a> when you&#39;re ready for the real thing.</p><h2 id="_10-watch-the-leaderboard" tabindex="-1">10. Watch the leaderboard <a class="header-anchor" href="#_10-watch-the-leaderboard" aria-label="Permalink to &quot;10. Watch the leaderboard&quot;">​</a></h2><p>During an event, the <strong>Leaderboard</strong> is how everyone follows things as they unfold. It updates live: every radio punch, every card download, every status change appears the moment it happens. No refreshing, no re-running a report.</p><p>While the event is live, open <strong>Leaderboard</strong> under <strong>Race</strong> in the event menu to see it inside Manager (see <a href="./../screens/leaderboard">Leaderboard</a>). For a TV, open <strong>Screens</strong> (under <strong>Race → Admin</strong>) and click the name of the built-in <strong>all</strong> screen. It opens in a new browser tab, showing every class: the current finishers, who&#39;s still out, and how the order changes as new results come in. This is the view you&#39;d put on a TV at the arena, or keep open on a second screen while you work.</p><p><img src="'+I+'" alt="A leaderboard screen with two classes side by side: finishers with places at the top, and runners still on course below"></p><p>The <strong>Screens</strong> page lists every screen that has been opened, what it shows and which classes, with <strong>New</strong> to set up more and <strong>Leaderboard classes</strong> beside it:</p><p><img src="'+P+'" alt="The Screens page listing three TV screens with their content, classes, last heard from and resolution, and the Commentary section below"></p><p>For more on screens and their configuration, see <a href="./../screens/creating-screens">Creating screens</a> and <a href="./../screens/tv-screens">TV screens</a>.</p><h2 id="_11-view-the-results" tabindex="-1">11. View the results <a class="header-anchor" href="#_11-view-the-results" aria-label="Permalink to &quot;11. View the results&quot;">​</a></h2><p>The <strong>Results</strong> page is the operator&#39;s view of the same data — detailed, filterable, built for checking and exporting rather than live display.</p><p>Open <strong>Results</strong> under <strong>Race</strong> in the event menu. You&#39;ll see results grouped by class.</p><p>For each class, competitors are listed in finishing order with their time. Competitors with a problem status like MP or DNF appear below the finishers.</p><p>Use the panel on the right to:</p><ul><li><strong>Group by</strong> class or course, and pick <strong>Classes</strong> / <strong>Courses</strong> or an <strong>Organisation</strong> to narrow the list.</li><li><strong>Show behind time</strong> to see the gap to the leader, and <strong>Show summary</strong> for the counts at the top of each class.</li><li><strong>Include</strong> competitors who are normally left out: <strong>Provisional results</strong>, <strong>On course competitors</strong>, <strong>Status none competitors</strong> and <strong>Did not start</strong>. These change what <em>you</em> see on screen only — an exported results file always accounts for everyone who took part, whatever is ticked here. See <a href="./../reference/status-and-race-time#what-an-exported-results-file-contains">What an exported results file contains</a>.</li></ul><p>When you&#39;re ready to share results, open <strong>Publish</strong> at the top of the page:</p><p><img src="'+A+'" alt="The Results page with the Publish menu open: Export IOF XML…, Export JSON…, Export PDF…, Print view… and Print to splits printer…"></p><ul><li><strong>Upload to Eventor…</strong> sends results straight to Eventor from within Manager (offered when Eventor is set up).</li><li><strong>Export IOF XML…</strong> downloads a results file for other systems (or to upload to Eventor by hand). <strong>Export JSON…</strong> and <strong>Export PDF…</strong> are beside it.</li><li><strong>Print view…</strong> gives you a printable version, and <strong>Print to splits printer…</strong> prints the results on the <a href="./../running-the-event/splits-printing">splits printer</a>.</li></ul><p>When you&#39;ve finished, click the <strong>Live</strong> button in the app bar and choose <strong>Finish event</strong> to move the event to <strong>Archive</strong>.</p><p><img src="'+O+'" alt="The Live state menu open under the green Live button: Finish event, and Events — Back to events list"></p><p>If competitors still have no settled result, Manager lists them first under <strong>Event not finalised</strong>, with buttons to settle them, or <strong>Finish anyway</strong>:</p><p><img src="'+M+'" alt="The Event not finalised dialog: counts of competitors with no status, on course, and radio finishes whose card was not downloaded, with buttons to settle them"></p><p>For the full details, see <a href="./../after-the-event/results">Results</a>.</p><h2 id="_12-what-s-next" tabindex="-1">12. What&#39;s next <a class="header-anchor" href="#_12-what-s-next" aria-label="Permalink to &quot;12. What&#39;s next&quot;">​</a></h2><p>You&#39;ve just walked through the core loop of meshO Manager — create an event, define its structure, register competitors, download cards, and view results. A real event adds more layers:</p><ul><li><strong>Importing data</strong> from Eventor, IOF XML, or Purple Pen so you don&#39;t type everything by hand. See <a href="./../event-setup/import-event-data">Importing event data</a>.</li><li><strong>Connecting meshO Prime</strong> to get live radio punches from controls in the forest. See <a href="./../running-the-event/connecting-prime-and-radios">Connecting meshO Prime and radios</a>.</li><li><strong>Setting up spectator screens</strong> on TVs at the arena. See <a href="./../screens/creating-screens">Creating screens</a> and <a href="./../screens/tv-screens">TV screens</a>.</li><li><strong>Letting competitors follow on their phones</strong>, and a kiosk at the finish. See <a href="./../screens/spectator-site-and-kiosk">The spectator site and kiosk</a>.</li><li><strong>Running commentary</strong> for the announcer. See <a href="./../screens/commentary">Commentary</a>.</li><li><strong>Handling problems</strong> — missing punches, unknown cards, overdue competitors. See <a href="./../running-the-event/resolving-issues">Resolving issues on the day</a>.</li><li><strong>Multiple operators</strong> working simultaneously on different laptops. See <a href="./../reference/multi-operator-setup">Multi-operator setup</a> — remember, Manager is multi-user by default. Other volunteers just open the same URL in their browser.</li><li><strong>An entry desk</strong> for on-the-day entries and hire cards. See <a href="./../running-the-event/registration-desk">The registration desk</a> and <a href="./../running-the-event/hire-items">Hire items</a>.</li><li><strong>Accounting for everyone</strong> at the end of the day. See <a href="./../running-the-event/safety-check">Safety check</a>.</li></ul><p>Before your first real competition, work through the <a href="./../event-setup/pre-event-checklist">Pre-event checklist</a> to make sure nothing is forgotten.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../what-is-mesho-manager/">What is meshO Manager?</a> — the architecture behind what you just used.</li><li><a href="./../download-and-install/">Download, install and update</a></li><li><a href="./concepts-glossary">Concepts and glossary</a></li><li><a href="./../event-setup/create-event">Creating an event</a></li><li><a href="./../running-the-event/dashboard">The event dashboard</a></li><li><a href="./../running-the-event/card-download">Downloading cards</a></li></ul>',137)])])}const V=s(R,[["render",D]]);export{H as __pageData,V as default};
